SELECT count(*) FROM public.chartevents chartevents
  LEFT JOIN (SELECT key1, 1 AS hit FROM (SELECT po.hadm_id AS key1 FROM public.poe po WHERE po.order_provider_id = 'P57YCB' INTERSECT SELECT a.hadm_id AS key1 FROM public.admissions a, public.drgcodes g, public.services s WHERE a.admission_type = 'URGENT' AND g.hadm_id = a.hadm_id AND g.drg_type = 'APR' AND g.drg_severity >= 3 AND s.hadm_id = a.hadm_id) x) b1 ON chartevents.hadm_id = b1.key1
  LEFT JOIN (SELECT DISTINCT d.charttime AS key1, d.stay_id AS key2, 1 AS hit FROM (SELECT DISTINCT charttime, stay_id FROM public.chartevents) d, public.icustays i, public.transfers t, public.patients p, public.microbiologyevents m WHERE t.hadm_id = i.hadm_id AND t.careunit = i.first_careunit AND p.subject_id = i.subject_id AND p.anchor_age >= 60 AND m.hadm_id = i.hadm_id AND m.interpretation = 'R' AND d.charttime >= t.intime AND d.charttime <= t.outtime AND d.stay_id = i.stay_id) b2 ON chartevents.charttime = b2.key1 AND chartevents.stay_id = b2.key2
WHERE (b1.hit IS NOT NULL OR b2.hit IS NOT NULL);
